using System;using System.Collections.Generic;using Exoduser.UnityPort.Core.Combat;using Exoduser.UnityPort.Core.Skills;
namespace Exoduser.UnityPort.Core {
 public sealed class GhostPathPoint {public float X,Y;public GhostPathPoint(float x,float y){X=x;Y=y;}}
 public sealed class GhostMarkedTarget {public EnemyState Enemy;public float X,Y;}
 public sealed class GhostDetonation {public float X,Y,Radius;public int T,MaxT=60,Stacks;}
 public sealed partial class Simulation {
  public bool GhostWalkActive;public int GhostWalkTicks,GhostWalkMax,GhostWalkCount;public float GhostWalkCd;
  public readonly List<GhostPathPoint> GhostPath=new List<GhostPathPoint>();readonly List<EnemyState> ghostMarked=new List<EnemyState>();readonly HashSet<string> ghostHit=new HashSet<string>();
  public readonly List<GhostPathPoint> RainLightningForward=new List<GhostPathPoint>(),RainLightningReverse=new List<GhostPathPoint>();public readonly List<GhostMarkedTarget> RainLightningTargets=new List<GhostMarkedTarget>();public readonly List<GhostDetonation> GhostDetonations=new List<GhostDetonation>();
  public int RainLightningPhase,RainLightningIndex,RainLightningDamage,RainLightningWidth,RainLightningStacks;float rainEndX,rainEndY;
  bool CastGhostWalk(){if(GhostWalkActive){FinishGhostWalk();return true;}if(GhostWalkCd>0){DenySkill("ghostWalk","cooldown");return false;}int lv=Math.Max(1,Skills.Level("ghostWalk"));GhostWalkActive=true;GhostWalkTicks=GhostWalkCount=0;GhostWalkMax=Math.Min(300,120+(lv-1)*18);ghostHit.Clear();GhostPath.Clear();GhostPath.Add(new GhostPathPoint(Player.X,Player.Y));ghostMarked.Clear();GhostWalkCd=1200;Player.State="ghostWalk";Player.Poise=4;HurtShake(3);Cast("ghostWalk");return true;}
  partial void ActivateTimeStepGhost(){if(GhostWalkCd<=0)CastGhostWalk();}
  void FinishGhostWalk(){if(!GhostWalkActive)return;int lv=Math.Max(1,Skills.Level("ghostWalk")),baseDamage=Js.Int(MagicReference()*MagicDamageMultiplier()*SkillRules.SkMul("ghostWalk",lv)*SkillFuseMultiplier("ghostWalk"));GhostPath.Add(new GhostPathPoint(Player.X,Player.Y));RainLightningForward.Clear();RainLightningForward.AddRange(GhostPath);RainLightningReverse.Clear();for(int i=GhostPath.Count-1;i>=0;i--)RainLightningReverse.Add(GhostPath[i]);RainLightningPhase=RainLightningIndex=0;RainLightningDamage=Js.Int(baseDamage*(1+GhostWalkCount*.1));RainLightningWidth=80+(lv-1)*8;RainLightningTargets.Clear();foreach(var e in ghostMarked)RainLightningTargets.Add(new GhostMarkedTarget{Enemy=e,X=e.X,Y=e.Y});RainLightningStacks=GhostWalkCount;rainEndX=Player.X;rainEndY=Player.Y;Player.State="rainLightning";GhostWalkActive=false;GhostWalkTicks=GhostWalkCount=0;ghostHit.Clear();GhostPath.Clear();ghostMarked.Clear();Player.Iframes=Math.Max(Player.Iframes,120);}
  bool TickGhostMovement(float x,float y){if(Player.State=="ghostWalk"){MovePlayer(x,y,2,false,false);return true;}if(Player.State!="rainLightning")return false;Player.Iframes=Math.Max(Player.Iframes,5);var path=RainLightningPhase==0?RainLightningReverse:RainLightningForward;if(path.Count==0){if(RainLightningPhase==0){RainLightningPhase=1;RainLightningIndex=0;}else CompleteRainLightning();return true;}int speed=Math.Max(4,path.Count/3),targetCount=RainLightningTargets.Count,nextBomb=targetCount>0?path.Count/(targetCount+1):9999;for(int i=0;i<speed;i++){RainLightningIndex++;if(RainLightningIndex>=path.Count){if(RainLightningPhase==0){RainLightningPhase=1;RainLightningIndex=0;HurtShake(12);}else CompleteRainLightning();break;}var p=path[RainLightningIndex];Player.X=p.X;Player.Y=p.Y;if(RainLightningIndex>0){var previous=path[RainLightningIndex-1];Player.Facing=(float)Math.Atan2(p.Y-previous.Y,p.X-previous.X);}if(RainLightningPhase==1&&targetCount>0&&RainLightningTargets.Count>0&&nextBomb>0&&RainLightningIndex%nextBomb==0)DetonateNextGhostTarget();}return true;}
  void DetonateNextGhostTarget(){var t=RainLightningTargets[0];RainLightningTargets.RemoveAt(0);GhostDetonate(t.Enemy.Alive?t.Enemy.X:t.X,t.Enemy.Alive?t.Enemy.Y:t.Y);}
  void CompleteRainLightning(){while(RainLightningTargets.Count>0)DetonateNextGhostTarget();Player.X=rainEndX;Player.Y=rainEndY;GhostDetonate(Player.X,Player.Y);RainLightningForward.Clear();RainLightningReverse.Clear();Player.State="idle";Player.Iframes=Math.Max(Player.Iframes,30);}
  void GhostDetonate(float x,float y){float radius=RainLightningWidth+40;foreach(var e in Enemies.ToArray()){if(!e.Alive||ZoneDistance(x,y,e.X,e.Y)>=radius+e.Radius)continue;double a=Math.Atan2(e.Y-y,e.X-x);ApplyEnemyDamage(e,RainLightningDamage,(float)a,false,3,atkEl:4,poiseMult:2,sourceOptions:new EnemyHurtOpts{kbMult=3,poiseMult=2},silent:false);e.Stunned=Math.Max(e.Stunned,60);e.KnockbackX+=(float)(Math.Cos(a)*25);e.KnockbackY+=(float)(Math.Sin(a)*25);}
   int count=4+RainLightningStacks/8;for(int i=0;i<count;i++){double a=Math.PI*2*i/count;PlayerSkillProjectiles.Add(new PlayerSkillProjectile{Id=nextPlayerSkillProjectileId++,X=x,Y=y,Vx=Math.Cos(a)*8,Vy=Math.Sin(a)*8,Damage=Js.Int(RainLightningDamage*.5),Element=4,MaxDist=200+RainLightningStacks*5,Radius=5,Stagger=2,Knockback=2,Magic=true,ChainMax=2,ChainRange=120,PierceProbability=1,PierceMax=1});}HurtShake(15);GhostDetonations.Add(new GhostDetonation{X=x,Y=y,Radius=radius,Stacks=RainLightningStacks});}
  void TickGhostLate(){for(int i=GhostDetonations.Count-1;i>=0;i--)if(++GhostDetonations[i].T>=GhostDetonations[i].MaxT)GhostDetonations.RemoveAt(i);if(GhostWalkActive){GhostWalkTicks++;Player.Iframes=Math.Max(Player.Iframes,3);int cap=Math.Min(50,Math.Max(1,Skills.Level("ghostWalk"))*5);for(int i=0;i<Enemies.Count&&GhostWalkCount<cap;i++){var e=Enemies[i];if(!e.Alive)continue;string key="e"+(e.Id!=0?e.Id:i);if(ghostHit.Contains(key))continue;if(ZoneDistance(Player.X,Player.Y,e.X,e.Y)<Player.Radius+e.Radius+20){ghostHit.Add(key);GhostWalkCount++;ghostMarked.Add(e);}}
   if(Druid!=null)for(int i=0;i<Druid.Projectiles.Count&&GhostWalkCount<cap;i++){var p=Druid.Projectiles[i];string key="p"+i+"_"+Js.Int(p.X)+"_"+Js.Int(p.Y);if(ghostHit.Contains(key))continue;if(ZoneDistance(Player.X,Player.Y,p.X,p.Y)<Player.Radius+p.R+15){ghostHit.Add(key);GhostWalkCount++;}}
   if(GhostPath.Count>0){var last=GhostPath[GhostPath.Count-1];if(ZoneDistance(Player.X,Player.Y,last.X,last.Y)>=30)GhostPath.Add(new GhostPathPoint(Player.X,Player.Y));}if(GhostWalkTicks>=GhostWalkMax)FinishGhostWalk();}
   if(GhostWalkCd>0){float bonus=0;foreach(var z in FireZones)if(z.Type=="holyDome"&&ZoneDistance(Player.X,Player.Y,z.X,z.Y)<z.R){bonus=1;break;}GhostWalkCd-=1+bonus;}
  }
 }
}